local utils = require 'mp.utils'local luts = {}local current_index = 0local function scan_luts()    local dir = mp.command_native({"expand-path", "~~/luts"})    local files = utils.readdir(dir, "files")    if not files then return end    for _, file in ipairs(files) do        local ext = file:match("%.([^%.]+)$")        if ext then            ext = ext:lower()            if ext == "cube" or ext == "3dl" or ext == "lut" or ext == "mga" then                table.insert(luts, "~~/luts/" .. file)            end        end    end    table.sort(luts)endlocal function apply_lut(index)    if index == 0 then        mp.set_property("lut", "")        mp.osd_message("LUT None", 2)    else        local path = luts[index]        local name = path:match("([^/]+)$"):gsub("%.[^%.]+$", "")        mp.set_property("lut", path)        mp.osd_message(string.format("LUT %d/%d %s", index, #luts, name), 2)    endendlocal function cycle_lut(direction)    if #luts == 0 then        mp.osd_message("No LUTs found", 3)        return    end    current_index = current_index + direction    if current_index > #luts then        current_index = 0    elseif current_index < 0 then        current_index = #luts    end    apply_lut(current_index)endscan_luts()mp.add_key_binding("e", "lut-cycle-next", function() cycle_lut(1) end)mp.add_key_binding("E", "lut-cycle-prev", function() cycle_lut(-1) end)